function translationChunks(value:string,maxLength=3000){const chunks:string[]=[];let current='';for(const paragraph of value.split(/\n+/)){for(const word of paragraph.split(/\s+/).filter(Boolean)){if(current&&current.length+word.length+1>maxLength){chunks.push(current);current=word}else current=current?`${current} ${word}`:word}if(current)current+='\n\n'}if(current.trim())chunks.push(current.trim());return chunks}
function readingPages(value:string,maxLength=2200){const pages:string[]=[];let current='';for(const paragraph of value.split(/\n+/)){const words=paragraph.split(/\s+/).filter(Boolean);let piece='';for(const word of words){if(piece&&piece.length+word.length+1>maxLength){if(current&&current.length+piece.length+2>maxLength){pages.push(current.trim());current=''}current+=`${current?'\n\n':''}${piece}`;piece=''}piece=piece?`${piece} ${word}`:word}if(piece){if(current&&current.length+piece.length+2>maxLength){pages.push(current.trim());current=''}current+=`${current?'\n\n':''}${piece}`}}if(current.trim())pages.push(current.trim());return pages.length?pages:['']}
