useEffect(()=>{let active=true;const t=setTimeout(()=>setWelcome(false),2200);api('/auth/me').then(async(u:User|null)=>{if(!active)return;if(!u){setUser(null);setOfflineMode(false);await offlineDelete('user');return}setUser(u);void offlineSet('user',u);loadLibrary()}).catch(async()=>{const cachedUser=await offlineGet<User>('user');if(!active||!cachedUser)return;setUser(cachedUser);setOfflineMode(true);const [cachedBooks,cachedLibrary]=await Promise.all([offlineGet<Book[]>(`books:${cachedUser.id}`),offlineGet<any>(`library:${cachedUser.id}`)]);if(cachedBooks)setBooks(cachedBooks);if(cachedLibrary){setLibraryBooks(cachedLibrary.books||[]);setFavoriteIds(new Set(cachedLibrary.favorites||[]));setSavedIds(new Set(cachedLibrary.saved||[]))}});return()=>{active=false;clearTimeout(t)}},[]);
useEffect(()=>{if(user){settingsReady.current=false;api('/settings').then((s:any)=>{setDark(s.theme==='dark');setFontSize(s.fontSize)}).catch(()=>{}).finally(()=>{settingsReady.current=true})}},[user]);
