async function loadLibrary(){try{const d=await api('/library');setFavoriteIds(new Set(d.favorites.map((x:any)=>x.bookId)));setSavedIds(new Set(d.saved.map((x:any)=>x.bookId)));const rows=[...d.favorites,...d.saved].map((x:any)=>({...x.book,formats:typeof x.book.formats==='string'?JSON.parse(x.book.formats):x.book.formats}));const snapshot=[...new Map<string,Book>(rows.map((b:Book)=>[b.id,{...b,categories:Array.isArray(b.categories)?b.categories:JSON.parse(b.categories||'[]')} ] as [string,Book])).values()];setLibraryBooks(snapshot);if(user)void offlineSet(`library:${user.id}`,{books:snapshot,favorites:d.favorites.map((x:any)=>x.bookId),saved:d.saved.map((x:any)=>x.bookId)})}catch{if(user){const cached=await offlineGet<any>(`library:${user.id}`);if(cached){setLibraryBooks(cached.books||[]);setFavoriteIds(new Set(cached.favorites||[]));setSavedIds(new Set(cached.saved||[]))}}}}
async function login(e:React.FormEvent){e.preventDefault();setLoginError('');try{const u=await api('/auth/login',{method:'POST',body:JSON.stringify({email,password})});setUser(u);setOfflineMode(false);void offlineSet('user',u);loadLibrary()}catch(err){setLoginError((err as Error).message)}}
async function discover(page=1,append=false,lang=language,topic=discoveryTopic,sort=discoverySort,keepExisting=false){setLearnerOnly(false);learnerSavedBooks.current=null;const requestId=++catalogRequest.current;if(!append){setPageNum(1);if(!keepExisting)setBooks([]);setCatalogTotal(0);setDiscoveryTopic(topic);setDiscoverySort(sort);setSelectedCategory('All')}setBusy(true);setError('');setStatusMessage('');try{const requestPage=async(n:number)=>{const p=new URLSearchParams({language:lang,page:String(n),...(topic?{topic}:{}),sort});return api(`/books/discover?${p}`)};const d=await requestPage(page);if(requestId!==catalogRequest.current)return;setOfflineMode(false);setCatalogTotal(d.catalogTotal||0);let merged:Book[]=append?[...new Map<string,Book>([...books,...d.results].map((b:Book)=>[b.id,b] as [string,Book])).values()]:d.results;setBooks(merged);if(user)void offlineSet(`books:${user.id}`,merged);let more=d.hasMore;let currentPage=page;setHasMore(more);setPageNum(currentPage);if(!d.results.length&&!append)setError('No books found in this language. Try another language.');
// Keep the home request to one page; readers can fetch more on demand.
}catch(err){if(requestId===catalogRequest.current){const cached=user?await offlineGet<Book[]>(`books:${user.id}`):undefined;if(cached?.length){setBooks(cached);setHasMore(false);setOfflineMode(true);setError('Offline mode: showing books saved on this phone.')}else setError((err as Error).message)}}finally{if(requestId===catalogRequest.current){setStatusMessage('');setBusy(false)}}}
async function search(q=query,lang=language){setLearnerOnly(false);learnerSavedBooks.current=null;const requestId=++catalogRequest.current;if(q.trim())setDiscoveryTopic('');setSelectedCategory('All');if(!q.trim()){await discover(1,false,lang);return}setPageNum(1);setBusy(true);setError('');setStatusMessage('');try{const p=new URLSearchParams({q,language:lang,page:'1'});const d=await api(`/books/search?${p}`);if(requestId!==catalogRequest.current)return;setOfflineMode(false);setCatalogTotal(d.catalogTotal||0);setBooks(d.results);if(user)void offlineSet(`books:${user.id}`,d.results);setHasMore(d.hasMore);setPageNum(1);if(!d.results.length)setError('This book has no free legal copy yet. Try another title or author.');if(d.partial)setStatusMessage('Some catalogs are temporarily unavailable. Showing results from the sources that responded.')}catch(err){if(requestId===catalogRequest.current){const cached=user?await offlineGet<Book[]>(`books:${user.id}`):undefined;if(cached?.length){setBooks(cached);setHasMore(false);setOfflineMode(true);setError('Offline mode: showing books saved on this phone.')}else setError((err as Error).message)}}finally{if(requestId===catalogRequest.current)setBusy(false)}}
async function showLearnerOnly(){if(learnerOnly){setLearnerOnly(false);setBooks(learnerSavedBooks.current||[]);learnerSavedBooks.current=null;return}learnerSavedBooks.current=books;setLearnerOnly(true);setLanguage('all');setSelectedCategory('All');setQuery('');setBusy(true);setError('');try{const d=await api('/books/discover?learner=1');setBooks(d.results);setHasMore(false);setPageNum(1)}catch(err){setError((err as Error).message)}finally{setBusy(false)}}
function openDetails(b:Book){setSelected(b);setDetailReady(false);setSuggestionsOpen(false);window.scrollTo({top:0,behavior:'instant'})}
function chooseSuggestion(b:Book){setQuery(b.title);setSearchSuggestions([]);openDetails(b)}
async function toggle(kind:'favorite'|'saved',b:Book){const set=kind==='favorite'?favoriteIds:savedIds;const path=`/library/${encodeURIComponent(b.id)}/${kind}`;try{if(set.has(b.id)){await api(path,{method:'DELETE'});const next=new Set(set);next.delete(b.id);kind==='favorite'?setFavoriteIds(next):setSavedIds(next);loadLibrary()}else{await api(path,{method:'PUT'});const next=new Set(set);next.add(b.id);kind==='favorite'?setFavoriteIds(next):setSavedIds(next);loadLibrary()}}catch(e){setError((e as Error).message)}}
useEffect(()=>{if(!user||offlineMode||tab!=='Home')return;let active=true;void (async()=>{const cached=await offlineGet<Book[]>(`books:${user.id}`);if(!active)return;if(cached?.length)setBooks(cached);void discover(1,false,'all','', 'new',true)})();return()=>{active=false}},[user?.id,offlineMode,tab]);
