 function playSpeechChunk(){const queue=speechRef.current;if(!queue||queue.active)return;if(queue.index>=queue.chunks.length){if(queue.loading)return;speechRef.current=null;setSpeechStatus('idle');setSpeechProgress('');return}queue.active=true;const index=queue.index,language=queue.locale.toLowerCase().startsWith('ta')?'ta':queue.locale.toLowerCase().startsWith('hi')?'hi':'en';setSpeechProgress(`Reading ${Math.min(index+1,queue.total)} / ${queue.total}`);void(async()=>{try{const response=await fetch(`${API}/speak`,{method:'POST',credentials:'include',headers:{'Content-Type':'application/json'},body:JSON.stringify({text:queue.chunks[index],language})});if(!response.ok){const error=await response.json().catch(()=>({}));throw Error(error.error||'The selected language voice is unavailable.')}const objectUrl=URL.createObjectURL(await response.blob());if(speechRef.current!==queue){URL.revokeObjectURL(objectUrl);return}const audio=queue.player||new Audio();audio.pause();audio.src=objectUrl;audio.loop=false;audio.volume=1;queue.player=audio;queue.audio=audio;queue.objectUrl=objectUrl;audio.onended=()=>{URL.revokeObjectURL(objectUrl);queue.objectUrl=undefined;queue.audio=undefined;if(speechRef.current!==queue)return;queue.active=false;queue.index++;playSpeechChunk()};audio.onerror=()=>{URL.revokeObjectURL(objectUrl);if(speechRef.current===queue){queue.active=false;speechRef.current=null;setSpeechStatus('idle');setMessage('Could not play the generated voice audio. Please try again.')}};if(queue.paused)return;await audio.play()}catch(error){if(speechRef.current===queue){queue.player?.pause();if(queue.objectUrl)URL.revokeObjectURL(queue.objectUrl);queue.active=false;speechRef.current=null;setSpeechStatus('idle');setSpeechProgress('');setMessage((error as Error).message||'Could not generate the selected language voice.')}}})()}
