function Profile({user,dark,setDark,appUpdateAvailable,updateChecking,updateMessage,onCheckForUpdate,onApplyUpdate,onLogout}:{user:User;dark:boolean;appUpdateAvailable:boolean;updateChecking:boolean;updateMessage:string;onCheckForUpdate:()=>void;setDark:(v:boolean)=>void;onApplyUpdate:()=>void;onLogout:()=>void}){const [showMemberPassword,setShowMemberPassword]=useState(false);const [members,setMembers]=useState<any[]>([]),[email,setEmail]=useState(''),[password,setPassword]=useState(''),[message,setMessage]=useState('');useEffect(()=>{if(user.role==='ADMIN')api('/admin/members').then(setMembers).catch(()=>{})},[user.role]);async function add(e:React.FormEvent){e.preventDefault();setMessage('');try{await api('/admin/members',{method:'POST',body:JSON.stringify({email,password})});setPassword('');setMessage('Member added.');setMembers(await api('/admin/members'))}catch(err){setMessage((err as Error).message)}}return <section className="profile"><span className="eyebrow">YOUR SPACE</span><h1>Reading, your way.</h1><button className="setting-row update-check-row" onClick={onCheckForUpdate} disabled={updateChecking}><span>App updates</span><b>{updateChecking?'Checking…':'Check now'}</b></button>{updateMessage&&<p className="update-status" role="status">{updateMessage}</p>}{appUpdateAvailable&&<div className="update-alert" role="status"><div><b>Update available</b><span>A new version of its you is ready.</span></div><button className="primary" onClick={onApplyUpdate}>Update now</button></div>}<div className="settings-card"><div className="avatar big">{user.email[0].toUpperCase()}</div><div><b>{user.email}</b><span>{user.role==='ADMIN'?'Library administrator':'Approved member'}</span></div></div><button className="setting-row" onClick={()=>setDark(!dark)}><span><Moon/> Reading theme</span><b>{dark?'Dark':'Light'}</b></button><button className="setting-row" onClick={onLogout}><span><LogOut/> Sign out</span><b>→</b></button>{user.role==='ADMIN'&&<section className="admin-card"><span className="eyebrow">ADMIN ONLY · MAXIMUM 5 ACCOUNTS</span><h2>Approved members</h2><div className="member-list">{members.map(m=><div key={m.id}><span>{m.email}</span><div><button onClick={async()=>{await api(`/admin/members/${m.id}`,{method:'PATCH',body:JSON.stringify({active:!m.active})});setMembers(await api('/admin/members'))}}>{m.active?'Disable':'Enable'}</button><button onClick={async()=>{const next=window.prompt(`New password for ${m.email} (12+ characters)`);if(next){try{await api(`/admin/members/${m.id}/reset-password`,{method:'POST',body:JSON.stringify({password:next})});setMessage('Password reset.')}catch(e){setMessage((e as Error).message)}}}}>Reset password</button></div></div>)}</div>{members.length<5&&<form onSubmit={add} className="member-form"><input type="email" placeholder="Member email" value={email} onChange={e=>setEmail(e.target.value)} required/><div className="password-input-wrap"><input type={showMemberPassword?'text':'password'} minLength={12} placeholder="Temporary password (12+ chars)" value={password} onChange={e=>setPassword(e.target.value)} required/><button type="button" className="password-toggle" aria-label={showMemberPassword?'Hide password':'Show password'} title={showMemberPassword?'Hide password':'Show password'} onClick={()=>setShowMemberPassword(!showMemberPassword)}>{showMemberPassword?<EyeOff size={16}/>:<Eye size={16}/>}</button></div><button className="primary"><Plus size={16}/> Add member</button></form>}{message&&<p>{message}</p>}</section>}</section>}

createRoot(document.getElementById('root')!).render(<React.StrictMode><App/></React.StrictMode>);
if('serviceWorker' in navigator)window.addEventListener('load',async()=>{
 if(import.meta.env.DEV){
  const registrations=await navigator.serviceWorker.getRegistrations();
  await Promise.all(registrations.map(registration=>registration.unregister()));
  const cacheNames=await caches.keys();
  await Promise.all(cacheNames.map(name=>caches.delete(name)));
  if(registrations.length&&sessionStorage.getItem('foryou.dev-sw-cleaned')!=='1'){
   sessionStorage.setItem('foryou.dev-sw-cleaned','1');
   window.location.reload();
  }
  return;
 }
 let refreshing=false;
 navigator.serviceWorker.addEventListener('controllerchange',()=>{if(!refreshing){refreshing=true;window.location.reload()}});
 navigator.serviceWorker.register('/sw.js').then(registration=>{
  const announceUpdate=(worker:ServiceWorker|null)=>{
   if(!worker||!navigator.serviceWorker.controller)return;
   (window as any).__foryouApplyUpdate=()=>worker.postMessage({type:'SKIP_WAITING'});
   window.dispatchEvent(new Event('foryou:update-available'));
  };
  if(registration.waiting)announceUpdate(registration.waiting);
  registration.addEventListener('updatefound',()=>{
   const worker=registration.installing;
   worker?.addEventListener('statechange',()=>{if(worker.state==='installed')announceUpdate(registration.waiting||worker)});
  });
  const checkForUpdate=()=>{if(document.visibilityState==='visible')registration.update().catch(()=>{})};
  window.addEventListener('focus',checkForUpdate);
  document.addEventListener('visibilitychange',checkForUpdate);
 }).catch(()=>{});
});
